import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../api';

const AuthPage = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({ email: '', password: '', username: '' });
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (isLogin) {
        await api.login({ email: formData.email, password: formData.password });
        navigate('/');
      } else {
        await api.register(formData);
        setIsLogin(true);
        alert("Успех! Теперь войдите.");
      }
    } catch (err) { alert("Ошибка!"); }
  };

  return (
    <div style={{ display:'flex', justifyContent:'center', marginTop:'50px' }}>
      <form onSubmit={handleSubmit} style={{ display:'flex', flexDirection:'column', gap:'10px', width:'300px' }}>
        <h2>{isLogin ? 'Вход' : 'Регистрация'}</h2>
        {!isLogin && <input placeholder="Логин (Username)" onChange={e=>setFormData({...formData, username:e.target.value})} required />}
        <input placeholder="Email" onChange={e=>setFormData({...formData, email:e.target.value})} required />
        <input type="password" placeholder="Пароль" onChange={e=>setFormData({...formData, password:e.target.value})} required />
        <button type="submit" style={{background:'#d4418e', color:'white', border:'none', padding:'10px'}}>{isLogin ? 'Войти' : 'Создать аккаунт'}</button>
        <p onClick={()=>setIsLogin(!isLogin)} style={{cursor:'pointer', color:'blue'}}>{isLogin ? 'Нет аккаунта? Регистрация' : 'Есть аккаунт? Вход'}</p>
      </form>
    </div>
  );
};
export default AuthPage;
